#!/usr/bin/env python3
"""Закрытый правами файл НАЗЫВАЕТСЯ, а не выпадает из обхода молча.

Сценарий пришёл из внешней проверки и переписан здесь регрессией ПРАВИЛЬНОГО
поведения.

Обход секретов начинался так:

    for path, label in targets:
        if not path.is_file():
            continue

`Path.is_file()` проглатывает отказ в доступе и возвращает False. Файл, который
СУЩЕСТВУЕТ, но закрыт правами, — обычное дело для управляемой политики
организации и для чужого профиля — пропадал из обхода наравне с
несуществующим, и в списке непрочитанного о нём не было ни слова. Цена ровно
одна и она вся в докладе: «секретов не найдено» про файл, который ни разу не
открывали.

Правильное поведение стояло СТРОКОЙ НИЖЕ, в соседней ветке того же цикла: файл
есть, но не разобран — назвать его непрочитанным, потому что секрет мог быть
именно там. Дисциплина была сформулирована и не применена к отказу в доступе.

Различитель для этого в сборщике уже был — `_scope_state`, которым читаются
области настроек. Второго здесь не заводится: два независимых признака одного
и того же расходятся, и расходятся молча.

Что здесь заперто:
  · закрытая правами цель названа непрочитанной, и причина названа словом —
    «не пустили», а не «не разобран»: причины разные и лечатся разными людьми;
  · доклад по такой машине НЕ утверждает, что секретов там нет: закрытый файл
    доезжает до отчёта как неизмеренная область и гасит доверие к нему;
  · отсутствующего файла в непрочитанных НЕТ — «нечего смотреть» это не
    проблема, и раздувать список нечем;
  · существующий, но неразобранный файл остался при своей прежней причине и не
    смешался с новой;
  · список просмотренных файлов настроек различает три состояния: смотрели,
    нечего смотреть, не пустили;
  · обратный контроль: обычный читаемый файл просматривается ровно как прежде,
    и секрет в нём находится.

Настоящий профиль человека и настоящая управляемая политика машины здесь НЕ
ЧИТАЮТСЯ ни разу: профиль сборщика подменён временным каталогом, каталог
проекта задан явно, адрес общего конфига и адреса управляемых файлов
переставлены во временный каталог — и это проверяется отдельным классом, а не
обещается словами.

Порядок и состав областей тест НЕ переписывает у себя: он берёт их у самого
сборщика и подменяет только адреса управляемых файлов.

Права закрываются `chmod`. Там, где это ничего не закрывает, проверка
ПРОПУСКАЕТСЯ С НАЗВАННОЙ ПРИЧИНОЙ, а не зеленеет молча: под суперпользователем
права не помеха, и «зелено» означало бы только то, что ничего не проверяли.

Тест самодостаточен: только стандартная библиотека и сам инструмент.
"""
from __future__ import annotations

import importlib.util
import json
import os
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path

РЕПО = Path(__file__).resolve().parents[2]
ПАКЕТ = РЕПО / "plugins" / "superstack"
СБОРЩИК = ПАКЕТ / "tools" / "probe" / "collect.py"
СУДЬЯ = ПАКЕТ / "tools" / "adjudicate.py"
ПРАВИЛА = str(ПАКЕТ / "rules" / "*.json")


def _загрузить():
    spec = importlib.util.spec_from_file_location("ss_collect_closed", СБОРЩИК)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


collect = _загрузить()

#: Синтетический токен: форма настоящая, вещество выдумано. Ни повторов по
#: восемь символов, ни слов из словаря образцов — иначе сборщик справедливо
#: посчитал бы его плейсхолдером и обратный контроль проверял бы пустоту.
ТОКЕН = "ghp_A1b2C3d4" "E5f6G7h8I9j0" "K1l2M3n4O5"


def почему_нельзя_закрыть(закрытый: Path, цель: Path) -> "str | None":
    """Причина, по которой проверка прав здесь ничего не проверит. Или None.

    Молчаливый пропуск хуже отсутствия проверки: он выглядит как доказанное
    поведение. Поэтому каждая причина названа и попадает в вывод набора.
    """
    if os.name != "posix":
        return "не-POSIX: прав доступа в этом виде здесь нет — закрывать нечем"
    if hasattr(os, "geteuid") and os.geteuid() == 0:
        return ("прогон от суперпользователя: права доступа его не держат, "
                "и проверка зеленела бы, ничего не проверив")
    try:
        os.stat(цель)
    except PermissionError:
        return None
    except OSError as e:
        return f"каталог закрыт, но цель пропала совсем ({e}) — проверять нечего"
    return (f"chmod не закрыл доступ к {закрытый.name}: файловая система его "
            "не держит, и проверка зеленела бы, ничего не проверив")


class Машина(unittest.TestCase):
    """Временная машина: свой профиль, свой проект, своя управляемая политика."""

    def setUp(self):
        tmp = tempfile.TemporaryDirectory()
        self.addCleanup(tmp.cleanup)
        self.корень = Path(tmp.name)
        self.профиль = self.корень / ".claude"
        self.проект = self.корень / "проект"
        self.политика = self.корень / "политика"
        for каталог in (self.профиль, self.проект, self.политика):
            каталог.mkdir(parents=True)

        прежний_профиль = collect.CLAUDE
        collect.CLAUDE = self.профиль
        self.addCleanup(setattr, collect, "CLAUDE", прежний_профиль)

        # Общий конфиг хоста тоже читается обходом секретов. Без подмены он
        # увёл бы прогон в НАСТОЯЩИЙ `~/.claude.json` человека.
        прежний_общий = collect.global_config_path
        collect.global_config_path = lambda: self.корень / ".claude.json"
        self.addCleanup(setattr, collect, "global_config_path", прежний_общий)

        прежний_проект = os.environ.get("SUPERSTACK_PROJECT_DIR")
        os.environ["SUPERSTACK_PROJECT_DIR"] = str(self.проект)
        self.addCleanup(self._вернуть_проект, прежний_проект)

        self._подменить_управляемую()

    @staticmethod
    def _вернуть_проект(прежний) -> None:
        if прежний is None:
            os.environ.pop("SUPERSTACK_PROJECT_DIR", None)
        else:
            os.environ["SUPERSTACK_PROJECT_DIR"] = прежний

    def _подменить_управляемую(self) -> None:
        """Управляемые области — во временный каталог, каждая в свой.

        Порядок и состав областей берутся У САМОГО СБОРЩИКА: подменяются
        только два адреса. Разные каталоги нужны затем, чтобы закрытие одного
        не задевало второй: тогда «закрыто» и «нет вовсе» проверяются на одном
        прогоне и не путаются.
        """
        подмена = {"managed": self.политика / "managed-settings.json",
                   "managed-linux": self.корень / "линукс-политика.json"}
        список = [(метка, подмена.get(метка, путь))
                  for метка, путь in collect._settings_files()]
        self.управляемая = подмена["managed"]
        self.отсутствующая = подмена["managed-linux"]
        прежний = collect._settings_files
        collect._settings_files = lambda: список
        self.addCleanup(setattr, collect, "_settings_files", прежний)

    # ---- обвязка ------------------------------------------------------
    def записать(self, путь: Path, данные) -> Path:
        путь.parent.mkdir(parents=True, exist_ok=True)
        текст = данные if isinstance(данные, str) else json.dumps(
            данные, ensure_ascii=False)
        путь.write_text(текст, encoding="utf-8")
        return путь

    def закрыть_политику(self) -> None:
        """Закрыть каталог управляемой политики или пропустить с причиной."""
        self.записать(self.управляемая, {"permissions": {"defaultMode": "plan"}})
        os.chmod(self.политика, 0o000)
        self.addCleanup(os.chmod, self.политика, 0o700)
        причина = почему_нельзя_закрыть(self.политика, self.управляемая)
        if причина:
            self.skipTest(причина)

    def обойти(self) -> list:
        """Прогнать обход секретов начисто и вернуть находки."""
        collect.SECRET_SCAN_UNREADABLE.clear()
        return collect.scan_secrets_everywhere()

    def собрать(self) -> dict:
        collect.facts.clear()
        collect.SECRET_SCAN_UNREADABLE.clear()
        collect.probe_claude()
        return collect.facts

    def значение(self, ключ: str):
        факты = collect.facts
        self.assertIn(ключ, факты, f"факт {ключ} не собран")
        return факты[ключ]["value"]

    def непрочитанные(self) -> dict:
        """Непрочитанное обходом секретов, по метке файла."""
        return {з["file"]: з for з in collect.SECRET_SCAN_UNREADABLE}


class НеЧитаетНастоящуюМашину(Машина):
    """Обещание из заголовка, проверенное кодом, а не словами."""

    def test_все_области_лежат_во_временном_каталоге(self):
        for метка, путь in collect._settings_files():
            self.assertTrue(str(путь).startswith(str(self.корень)),
                            f"область {метка} ведёт наружу: {путь}")

    def test_управляемая_область_не_адрес_машины(self):
        адреса = {str(путь) for _метка, путь in collect._settings_files()}
        self.assertNotIn(
            "/Library/Application Support/ClaudeCode/managed-settings.json",
            адреса, "набор читает настоящую управляемую политику машины")
        self.assertNotIn("/etc/claude-code/managed-settings.json", адреса)

    def test_профиль_и_общий_конфиг_во_временном_каталоге(self):
        self.assertTrue(str(collect.CLAUDE).startswith(str(self.корень)))
        self.assertTrue(
            str(collect.global_config_path()).startswith(str(self.корень)),
            "обход секретов дотянулся бы до настоящего общего конфига")


class ЗакрытыйФайлНазван(Машина):
    """(а) Файл есть, но не пустили — он назван, и причина названа словом."""

    def test_закрытая_цель_попадает_в_непрочитанные(self):
        self.закрыть_политику()
        self.обойти()
        непрочитанные = self.непрочитанные()
        self.assertIn("managed", непрочитанные,
                      "закрытая правами цель выпала из обхода МОЛЧА — "
                      "доклад скажет «секретов не найдено» про файл, который "
                      "ни разу не открывали")
        self.assertEqual(непрочитанные["managed"]["path"], str(self.управляемая),
                         "названа метка, но не адрес: проверить нечем")

    def test_причина_названа_отказом_в_доступе(self):
        self.закрыть_политику()
        self.обойти()
        self.assertEqual(self.непрочитанные()["managed"].get("why"),
                         collect.НЕ_ПУСТИЛИ,
                         "«не пустили» и «не разобран» лечат разные люди: "
                         "первое — администратор, второе — владелец файла")

    def test_доклад_не_утверждает_что_секретов_там_нет(self):
        """Находок ноль — и ровно поэтому слепое пятно обязано быть названо."""
        self.закрыть_политику()
        self.assertEqual(self.обойти(), [],
                         "в закрытом файле что-то «нашлось» — значит его "
                         "прочитали, и проверка меряет не то")
        self.assertIn("managed", self.непрочитанные(),
                      "пустой список находок подан как чистая машина")

    def test_состояние_видно_и_в_фактах(self):
        self.закрыть_политику()
        self.собрать()
        self.assertIn("managed", {з["file"] for з
                                  in self.значение("sec.scan_unreadable")})
        self.assertNotIn("managed", self.значение("sec.scan_files"),
                         "«не пустили» подано как «смотрели и там чисто»")


class ОтсутствующийФайлНеПроблема(Машина):
    """(б) Файла нет вовсе — он не назван непрочитанным."""

    def test_отсутствующая_область_не_попадает_в_непрочитанные(self):
        self.обойти()
        self.assertNotIn("managed-linux", self.непрочитанные(),
                         "«нечего смотреть» подано как «не смогли посмотреть»")

    def test_отсутствующей_области_нет_ни_в_одном_из_трёх_списков(self):
        self.собрать()
        self.assertNotIn("managed-linux", self.значение("sec.scan_files"))
        self.assertNotIn("managed-linux", self.значение("sec.scan_denied"))
        self.assertNotIn("managed-linux",
                         {з["file"] for з in self.значение("sec.scan_unreadable")})


class НеразобранныйФайлПриСвоейПричине(Машина):
    """(в) Файл есть и не разобран — прежняя причина цела и не смешалась."""

    def test_битый_конфиг_по_прежнему_назван(self):
        self.записать(self.профиль / "settings.json", "{битый")
        self.обойти()
        self.assertIn("user", self.непрочитанные(),
                      "файл есть, но не разобран — секрет мог быть именно там")

    def test_битый_конфиг_не_выдан_за_отказ_в_доступе(self):
        self.записать(self.профиль / "settings.json", "{битый")
        self.обойти()
        self.assertNotEqual(self.непрочитанные()["user"].get("why"),
                            collect.НЕ_ПУСТИЛИ,
                            "две разные причины слиты в одну, и человек пойдёт "
                            "чинить не то")

    def test_обе_причины_различимы_на_одном_прогоне(self):
        self.закрыть_политику()
        self.записать(self.профиль / "settings.json", "{битый")
        self.обойти()
        непрочитанные = self.непрочитанные()
        self.assertIn("managed", непрочитанные)
        self.assertIn("user", непрочитанные)
        self.assertNotEqual(непрочитанные["managed"].get("why"),
                            непрочитанные["user"].get("why"),
                            "закрытый и битый неразличимы в докладе")


class ТриСостоянияРазличимы(Машина):
    """(2) Смотрели, нечего смотреть, не пустили — три ответа, а не два."""

    def test_каждое_состояние_имеет_своё_место_в_фактах(self):
        self.закрыть_политику()
        self.записать(self.профиль / "settings.json", {"env": {}})
        self.собрать()
        просмотрены = self.значение("sec.scan_files")
        закрыты = self.значение("sec.scan_denied")
        self.assertIn("user", просмотрены, "смотрели — и это не видно")
        self.assertIn("managed", закрыты, "не пустили — и это не видно")
        self.assertNotIn("managed-linux", просмотрены + закрыты,
                         "нечего смотреть — а сказано, что что-то было")
        self.assertEqual([м for м in просмотрены if м in закрыты], [],
                         "один файл объявлен и просмотренным, и закрытым")


class ЧитаемыйФайлПросматриваетсяКакПрежде(Машина):
    """(г) Обратный контроль. Проверка, ломающая здоровый путь, бесполезна."""

    def test_секрет_в_обычном_конфиге_находится(self):
        self.записать(self.профиль / "settings.json",
                      {"env": {"GITHUB_TOKEN": ТОКЕН}})
        находки = self.обойти()
        self.assertEqual([н["file"] for н in находки], ["user"])
        self.assertEqual(находки[0]["why"], "токен GitHub")
        self.assertEqual(self.непрочитанные(), {},
                         "здоровый файл записан в непрочитанные")

    def test_значение_секрета_наружу_не_уходит(self):
        self.записать(self.профиль / "settings.json",
                      {"env": {"GITHUB_TOKEN": ТОКЕН}})
        self.assertNotIn(ТОКЕН, json.dumps(self.обойти(), ensure_ascii=False))

    def test_читаемый_файл_числится_просмотренным(self):
        self.записать(self.профиль / "settings.json", {"env": {}})
        self.собрать()
        self.assertIn("user", self.значение("sec.scan_files"))
        self.assertEqual(self.значение("sec.scan_denied"), [],
                         "на здоровой машине кто-то объявлен закрытым")


class ДокладГаситДовериеКСебе(Машина):
    """Слепое пятно доезжает до ОТЧЁТА, а не остаётся внутри пробы.

    Проверяется настоящим судьёй и настоящими правилами продукта: утверждение
    «доклад не говорит, что там чисто» иначе оставалось бы моим утверждением
    о строке в списке, а не свойством того, что увидит человек.
    """

    def судить(self) -> dict:
        файл = self.корень / "факты.json"
        файл.write_text(json.dumps(collect.facts, ensure_ascii=False),
                        encoding="utf-8")
        r = subprocess.run(
            [sys.executable, str(СУДЬЯ), str(файл), ПРАВИЛА],
            capture_output=True, text=True, timeout=120,
            env={**os.environ, "SUPERSTACK_IGNORE_PAUSE": "1"})
        try:
            return json.loads(r.stdout)
        except ValueError:
            self.fail(f"судья не выдал отчёта (код {r.returncode}): "
                      f"{r.stderr.strip()[:300]}")

    def test_закрытый_файл_виден_отчёту_как_неизмеренная_область(self):
        self.закрыть_политику()
        self.собрать()
        отчёт = self.судить()
        секреты = [з for з in отчёт["unmeasured_scopes"]
                   if з.get("measurement") == "секреты"]
        self.assertEqual([з["file"] for з in секреты], ["managed"],
                         "закрытый файл не доехал до отчёта: «не нашёл» там "
                         "неотличимо от «там чисто»")
        self.assertEqual(секреты[0].get("why"), collect.НЕ_ПУСТИЛИ)
        self.assertFalse(отчёт["coverage"]["trustworthy"],
                         "отчёт по машине с непросмотренным файлом объявлен "
                         "полным")

    def test_на_здоровой_машине_неизмеренного_по_секретам_нет(self):
        """Обратный контроль: иначе проверка выше не могла бы упасть."""
        self.записать(self.профиль / "settings.json", {"env": {}})
        self.собрать()
        отчёт = self.судить()
        self.assertEqual([з for з in отчёт["unmeasured_scopes"]
                          if з.get("measurement") == "секреты"], [],
                         "на здоровой машине объявлено слепое пятно")


if __name__ == "__main__":
    unittest.main()
